    /// never by file and display name, which two components can share.
    pub key: String,
    /// The file that declares the component.
    pub file_path: Utf8PathBuf,
    /// The component's display name, for messages; the checker does not look the component up by it.
    pub display_name: String,
    /// How the module exports the component ([`ComponentEntry::exports`]): the checker asks for it by exactly these.
    /// It answers only for exported components and reports the rest as fallbacks.
    pub exports: Vec<ComponentExport>,
    /// Props the structural pass already has a description for. The checker is not asked for those: it is 65% of
    /// the requests on Mantine, and the merge keeps the structural description when the checker's is empty.
    pub described: rustc_hash::FxHashSet<String>,
    /// Which props `@types/react` declares the checker reports: `None` for all of them, else only these names. The
    /// session decides from `htmlAttributes` (`react_types::react_props_wanted`); the checker never filters by itself.
    pub react_wanted: Option<rustc_hash::FxHashSet<String>>,
}

/// A checker that answers for components as they are asked about, for a long-lived session.
///
/// `request` never blocks: it queues the targets and returns the receiver that yields the outcome once the checker
/// has it, so a caller can wait a bounded time and take the structural answer when the checker is slower.
/// reused while the checker would read the disk as it did (`caliper_docgen_semantic::resolve_cached`).
fn apply_semantic_backend(
    options: &caliper_docgen_core::pipeline::PipelineOptions,
    timeout: std::time::Duration,
    resolver: caliper_docgen_core::types::semantic::ResolverFacts,
    only: Option<&str>,
    pass: Pass,
    output: &mut caliper_docgen_core::types::ExtractionOutput,
) {
    let Some((project_root, tsconfig)) = semantic_setup(options) else {
        let outcome = caliper_docgen_core::types::semantic::SemanticOutcome::unavailable("no project directory");
        caliper_docgen_core::types::semantic::merge_semantic(output, outcome);
        return;
    };
    let mut targets = caliper_docgen_semantic::targets_of(output);
    if let Some(key) = only {
        targets.retain(|target| target.key == key);
    }
    let mut request = caliper_docgen_semantic::SemanticRequest::new(project_root, targets);
    request.tsconfig = tsconfig;
    request.request_timeout = timeout;
    let (teardown, started) = match pass {
        Pass::Extract(started) => (caliper_docgen_semantic::Teardown::OneShot, Some(started)),
        Pass::Check => (caliper_docgen_semantic::Teardown::Session, None),
    };
    let request = request.with_teardown(teardown);
    let outcome = match started {
        Some(started) if options.use_cache => {
            caliper_docgen_semantic::resolve_cached_early(request, &options.effective_cache_dir(), started.early)
        }
        Some(started) => caliper_docgen_semantic::resolve_early(request, started.early),
        None => caliper_docgen_semantic::resolve(request),
    };
    caliper_docgen_core::types::semantic::merge_semantic_with(output, outcome, resolver);
}
